Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
soc: ti: pruss: Fix double free in pruss_clk_mux_setup()

In the pruss_clk_mux_setup(), the devm_add_action_or_reset() indirectly
calls pruss_of_free_clk_provider(), which calls of_node_put(clk_mux_np)
on the error path. However, after the devm_add_action_or_reset()
returns, the of_node_put(clk_mux_np) is called again, causing a double
free.

Fix by returning directly, to avoid the duplicate of_node_put().

Fixes: ba59c9b43c86 ("soc: ti: pruss: support CORECLK_MUX and IEPCLK_MUX")
Cc: stable@vger.kernel.org
Signed-off-by: Wentao Liang <vulab@iscas.ac.cn>
Link: https://patch.msgid.link/20260113014716.2464741-1-vulab@iscas.ac.cn
Signed-off-by: Nishanth Menon <nm@ti.com>

Here is the root cause:
In pruss_clk_mux_setup(), devm_add_action_or_reset() already calls pruss_of_free_clk_provider() (which does of_node_put) on failure, but the error path also jumps to a label that does another of_node_put, causing double free.

Here is the patch:

 static int pruss_clk_mux_setup(struct pruss *pruss, struct clk *clk_mux,
 			       char *mux_name, struct device_node *clks_np)
 {
 	struct device_node *clk_mux_np;
 	struct device *dev = pruss->dev;
 	char *clk_mux_name;
 	unsigned int num_parents;
 	const char **parent_names;
 	void __iomem *reg;
 	u32 reg_offset;
 	int ret;

 	clk_mux_np = of_get_child_by_name(clks_np, mux_name);
 	if (!clk_mux_np) {
 		dev_err(dev, "%pOF is missing its '%s' node\n", clks_np,
 			mux_name);
 		return -ENODEV;
 	}

 	num_parents = of_clk_get_parent_count(clk_mux_np);
 	if (num_parents < 1) {
 		dev_err(dev, "mux-clock %pOF must have parents\n", clk_mux_np);
 		ret = -EINVAL;
 		goto put_clk_mux_np;
 	}

 	parent_names = devm_kcalloc(dev, sizeof(*parent_names), num_parents,
 				    GFP_KERNEL);
 	if (!parent_names) {
 		ret = -ENOMEM;
 		goto put_clk_mux_np;
 	}

 	of_clk_parent_fill(clk_mux_np, parent_names, num_parents);

 	clk_mux_name = devm_kasprintf(dev, GFP_KERNEL, "%s.%pOFn",
 				      dev_name(dev), clk_mux_np);
 	if (!clk_mux_name) {
 		ret = -ENOMEM;
 		goto put_clk_mux_np;
 	}

 	ret = of_property_read_u32(clk_mux_np, "reg", &reg_offset);
 	if (ret)
 		goto put_clk_mux_np;

 	reg = pruss->cfg_base + reg_offset;

 	clk_mux = clk_register_mux(NULL, clk_mux_name, parent_names,
 				   num_parents, 0, reg, 0, 1, 0, NULL);
 	if (IS_ERR(clk_mux)) {
 		ret = PTR_ERR(clk_mux);
 		goto put_clk_mux_np;
 	}

 	ret = devm_add_action_or_reset(dev, pruss_clk_unregister_mux, clk_mux);
 	if (ret) {
 		dev_err(dev, "failed to add clkmux unregister action %d", ret);
 		goto put_clk_mux_np;
 	}

 	ret = of_clk_add_provider(clk_mux_np, of_clk_src_simple_get, clk_mux);
 	if (ret)
 		goto put_clk_mux_np;

 	ret = devm_add_action_or_reset(dev, pruss_of_free_clk_provider,
 				       clk_mux_np);
-	if (ret) {
+	if (ret)
 		dev_err(dev, "failed to add clkmux free action %d", ret);
-		goto put_clk_mux_np;
-	}

-	return 0;
+	return ret;

 put_clk_mux_np:
 	of_node_put(clk_mux_np);
 	return ret;
 }



